'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const N = input[0];
const K = input[1];
const dolls = input.slice(2).sort((a, b) => a - b);

const INF = 1e100;
let prev = new Float64Array(N + 1); // Zero pairs: cost 0 for every prefix.

for (let j = 1; j <= K; j++) {
  const curr = new Float64Array(N + 1);
  curr.fill(INF);

  const maxPrefix = N - 3 * (K - j);

  for (let i = 1; i <= N; i++) {
    curr[i] = curr[i - 1];

    if (i >= 2 && i <= maxPrefix) {
      const cost = (dolls[i - 1] - dolls[i - 2]) ** 2;
      const candidate = prev[i - 2] + cost;
      if (candidate < curr[i]) curr[i] = candidate;
    }
  }

  prev = curr;
}

console.log(prev[N].toString());
